import{_ as e,c as i,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Finder 同步擴充功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/finder-sync.md","filePath":"zh-TW/guide/finder-sync.md","lastUpdated":1794112334000}'),o={name:"zh-TW/guide/finder-sync.md"};function n(l,a,d,s,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="finder-同步擴充功能" tabindex="-1">Finder 同步擴充功能 <a class="header-anchor" href="#finder-同步擴充功能" aria-label="Permalink to &quot;Finder 同步擴充功能&quot;">​</a></h1><h2 id="概覽" tabindex="-1">概覽 <a class="header-anchor" href="#概覽" aria-label="Permalink to &quot;概覽&quot;">​</a></h2><p>Nicasa Finder 同步擴充功能會在 macOS Finder 中加入一個工具列按鈕，讓你無需開啟 Nicasa 主應用程式就能快速處理圖片檔案。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h3><ul><li><strong>圖片最佳化工具</strong>：壓縮並最佳化選取的圖片</li><li><strong>AI 影像編輯器</strong>：用 AI 編輯選取的圖片（修復、增強、填補等）</li><li><strong>透過 Finder 工具列快速存取</strong></li><li><strong>支援同時選取多張圖片</strong></li></ul><h2 id="安裝與設定" tabindex="-1">安裝與設定 <a class="header-anchor" href="#安裝與設定" aria-label="Permalink to &quot;安裝與設定&quot;">​</a></h2><h3 id="透過-nicasa-應用程式安裝" tabindex="-1">透過 Nicasa 應用程式安裝 <a class="header-anchor" href="#透過-nicasa-應用程式安裝" aria-label="Permalink to &quot;透過 Nicasa 應用程式安裝&quot;">​</a></h3><p>Finder 同步擴充功能隨 Nicasa 主應用程式一起提供。安裝應用程式後，啟用該擴充功能：</p><ol><li>開啟 <strong>系統設定</strong> &gt; <strong>擴充功能</strong> &gt; <strong>Finder 擴充功能</strong></li><li>開啟 <strong>Nicasa Finder Sync</strong> 開關</li></ol><h3 id="工具列按鈕" tabindex="-1">工具列按鈕 <a class="header-anchor" href="#工具列按鈕" aria-label="Permalink to &quot;工具列按鈕&quot;">​</a></h3><p>啟用後，Finder 工具列中會出現一個 Nicasa 圖示。</p><p>如果沒有顯示：</p><ol><li>在 Finder 工具列上按右鍵</li><li>選擇 <strong>自訂工具列…</strong></li><li>把 Nicasa 按鈕拖到合適位置</li></ol><h2 id="使用-finder-工具列按鈕" tabindex="-1">使用 Finder 工具列按鈕 <a class="header-anchor" href="#使用-finder-工具列按鈕" aria-label="Permalink to &quot;使用 Finder 工具列按鈕&quot;">​</a></h2><h3 id="選取檔案" tabindex="-1">選取檔案 <a class="header-anchor" href="#選取檔案" aria-label="Permalink to &quot;選取檔案&quot;">​</a></h3><p>開啟 Finder 並選取一張或多張圖片。支援的格式：</p><ul><li><code>.jpg</code>、<code>.jpeg</code>、<code>.png</code>、<code>.gif</code>、<code>.bmp</code>、<code>.webp</code>、<code>.svg</code>、<code>.tiff</code>、<code>.ico</code></li></ul><h3 id="使用選單" tabindex="-1">使用選單 <a class="header-anchor" href="#使用選單" aria-label="Permalink to &quot;使用選單&quot;">​</a></h3><p>點擊 Nicasa 工具列按鈕，然後選擇：</p><table tabindex="0"><thead><tr><th>選項</th><th>說明</th></tr></thead><tbody><tr><td><strong>圖片最佳化工具</strong></td><td>壓縮並最佳化選取的圖片</td></tr><tr><td><strong>AI 影像編輯器</strong></td><td>在 Nicasa 的 AI 編輯器中開啟選取的圖片，進行修復、增強或影像填補</td></tr></tbody></table><blockquote><p>⚠️ <strong>注意</strong>：如果沒有選取任何檔案，按鈕會發出提示音且不會執行動作。</p></blockquote><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><ol><li>在 Finder 中選取圖片</li><li>點擊 Nicasa 工具列按鈕 → 選擇所需動作</li><li>Nicasa 應用程式會自動開啟並處理選取的圖片</li></ol><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li>為獲得最佳效果，請在你有存取權限的檔案夾中選取圖片</li><li>可以一次選取多個檔案</li><li>如果某張圖片無法開啟，請確認它屬於受支援的格式</li><li>該擴充功能與 macOS 沙盒機制良好配合——你只需在首次使用時授權存取</li></ul>',25)])])}const b=e(o,[["render",n]]);export{g as __pageData,b as default};
